UPDATE waiting_list wl
SET wl.status = 'notified',
    wl.is_notified = 1,
    wl.notification_date = NOW()
WHERE wl.user_id = #{userId}
  AND wl.status = 'waiting'
  AND wl.book_id IN (


        #{bid}


  )


UPDATE book b
JOIN (
    SELECT DISTINCT wl.book_id
    FROM waiting_list wl
    WHERE wl.user_id = #{userId}
      AND wl.status = 'notified'
      AND wl.book_id IN (


        #{bid}


      )
) w ON b.book_id = w.book_id
SET b.quantity = b.quantity - 1,
    b.available = CASE WHEN b.quantity - 1 <= 0 THEN FALSE ELSE b.available END
WHERE b.quantity > 0
